86	// Enqueue is best-effort: a write that lands locally but fails to enqueue must
87	// not fail condensation. The ref is still local; only its remote sync is missed
88	// until a later write to the same checkpoint re-enqueues it.
89	func (s *gitRefsStore) setRef(ctx context.Context, cid id.CheckpointID, hash plumbing.Hash) error {
90		refName := RefName(cid)
91		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
92			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
93		}
94		s.enqueueForPush(ctx, refName)
95		return nil
96	}
