1	package checkpoint
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11	
12		"github.com/go-git/go-git/v6"
13		"github.com/go-git/go-git/v6/plumbing"
14	
15		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
16	)
17	
18	// Push-discovery queue file names, kept in the git common dir so every worktree
19	// sharing the object store enqueues into one queue. The git-refs backend cannot
20	// push every local checkpoint ref at pre-push time (reads fetch refs too, and
21	// deleting them after push would hurt local workflows), so each write records
22	// the ref it touched here and pre-push drains + batch-pushes exactly those.
23	const (
24		pushQueueFileName = "entire-checkpoint-push-queue.jsonl"
25		pushQueueLockName = "entire-checkpoint-push-queue.lock"
26	)
27	
28	// pushQueueEntry is one JSONL record: a checkpoint ref awaiting push.
29	type pushQueueEntry struct {
30		Ref string `json:"ref"`
31	}
32	
33	// PushQueue is a flock-protected JSONL list of checkpoint refs awaiting push,
34	// stored in the git common dir. Entries are removed only after a confirmed push
35	// (Remove), so an interrupted or failed push leaves them for the next pre-push.
36	// Duplicates are tolerated on disk and collapsed by Drain.
37	type PushQueue struct {
38		dir string
39	}
40	
41	// NewPushQueue returns the push queue rooted at gitCommonDir.
42	func NewPushQueue(gitCommonDir string) *PushQueue {
43		return &PushQueue{dir: gitCommonDir}
44	}
45	
46	// PushQueueForRepo resolves the git common dir for repo and returns its queue.
47	func PushQueueForRepo(ctx context.Context, repo *git.Repository) (*PushQueue, error) {
48		dir, err := resolveGitCommonDir(ctx, repo)
49		if err != nil {
50			return nil, err
51		}
52		return NewPushQueue(dir), nil
53	}
54	
55	func (q *PushQueue) queuePath() string { return filepath.Join(q.dir, pushQueueFileName) }
56	func (q *PushQueue) lockPath() string  { return filepath.Join(q.dir, pushQueueLockName) }
57	
58	// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
59	// present (or already pushed): Drain collapses duplicates and the batch push is
60	// idempotent. Enqueue takes the lock so concurrent writers never interleave a
61	// partial line.
62	func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
63		release, err := flock.Acquire(q.lockPath())
64		if err != nil {
65			return fmt.Errorf("lock push queue: %w", err)
66		}
67		defer release()
68	
69		line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
70		if err != nil {
71			return fmt.Errorf("encode push queue entry: %w", err)
72		}
73		f, err := os.OpenFile(q.queuePath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
74		if err != nil {
75			return fmt.Errorf("open push queue: %w", err)
76		}
77		defer f.Close()
78		if _, err := f.Write(append(line, '\n')); err != nil {
79			return fmt.Errorf("append push queue entry: %w", err)
80		}
81		return nil
82	}
83	
84	// Drain returns the de-duplicated refs currently queued, in first-seen order. It
85	// does NOT remove them; call Remove after a confirmed push so a failed push
86	// retries next time. A missing queue file yields no refs.
87	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
88		release, err := flock.Acquire(q.lockPath())
89		if err != nil {
90			return nil, fmt.Errorf("lock push queue: %w", err)
91		}
92		defer release()
93		return q.readLocked()
94	}
95	
96	// Remove deletes the given refs from the queue, preserving any entries appended
97	// after a Drain (e.g. a write that landed during the push). Called after a
98	// confirmed push.
99	func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
100		if len(refs) == 0 {
101			return nil
102		}
103		release, err := flock.Acquire(q.lockPath())
104		if err != nil {
105			return fmt.Errorf("lock push queue: %w", err)
106		}
107		defer release()
108	
109		current, err := q.readLocked()
110		if err != nil {
111			return err
112		}
113		removed := make(map[string]struct{}, len(refs))
114		for _, r := range refs {
115			removed[r.String()] = struct{}{}
116		}
117		var buf bytes.Buffer
118		for _, r := range current {
119			if _, drop := removed[r.String()]; drop {
120				continue
121			}
122			line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
123			if err != nil {
124				return fmt.Errorf("encode push queue entry: %w", err)
125			}
126			buf.Write(line)
127			buf.WriteByte('\n')
128		}
129		if buf.Len() == 0 {
130			// Nothing left: drop the file so a clean repo has no stray queue.
131			if err := os.Remove(q.queuePath()); err != nil && !os.IsNotExist(err) {
132				return fmt.Errorf("remove empty push queue: %w", err)
133			}
134			return nil
135		}
136		if err := writeFileAtomicInDir(q.dir, q.queuePath(), buf.Bytes()); err != nil {
137			return fmt.Errorf("rewrite push queue: %w", err)
138		}
139		return nil
140	}
141	
142	// readLocked parses the queue file into de-duplicated refs, preserving first-seen
143	// order. The caller must hold the lock. Malformed lines are skipped rather than
144	// failing the whole drain — a single bad record must not strand every queued ref.
145	func (q *PushQueue) readLocked() ([]plumbing.ReferenceName, error) {
146		f, err := os.Open(q.queuePath())
147		if err != nil {
148			if os.IsNotExist(err) {
149				return nil, nil
150			}
151			return nil, fmt.Errorf("open push queue: %w", err)
152		}
153		defer f.Close()
154	
155		var refs []plumbing.ReferenceName
156		seen := make(map[string]struct{})
157		scanner := bufio.NewScanner(f)
158		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
159		for scanner.Scan() {
160			line := bytes.TrimSpace(scanner.Bytes())
161			if len(line) == 0 {
162				continue
163			}
164			var entry pushQueueEntry
165			if err := json.Unmarshal(line, &entry); err != nil || entry.Ref == "" {
166				continue
167			}
168			if _, dup := seen[entry.Ref]; dup {
169				continue
170			}
171			seen[entry.Ref] = struct{}{}
172			refs = append(refs, plumbing.ReferenceName(entry.Ref))
173		}
174		if err := scanner.Err(); err != nil {
175			return nil, fmt.Errorf("read push queue: %w", err)
176		}
177		return refs, nil
178	}
179	
180	// writeFileAtomicInDir writes data to a temp file in dir and renames it over
181	// path, so a reader (under the lock) never sees a half-written queue.
182	func writeFileAtomicInDir(dir, path string, data []byte) error {
183		tmp, err := os.CreateTemp(dir, pushQueueFileName+".*")
184		if err != nil {
185			return fmt.Errorf("create temp push queue: %w", err)
186		}
187		tmpName := tmp.Name()
188		defer os.Remove(tmpName)
189		if _, err := tmp.Write(data); err != nil {
190			_ = tmp.Close()
191			return fmt.Errorf("write temp push queue: %w", err)
192		}
193		if err := tmp.Close(); err != nil {
194			return fmt.Errorf("close temp push queue: %w", err)
195		}
196		if err := os.Rename(tmpName, path); err != nil {
197			return fmt.Errorf("rename temp push queue: %w", err)
198		}
199		return nil
200	}

