func checkpointShard(id string) string {
	if len(id) < 2 {
		return id
	}
	if len(id) == 26 {
		return id[len(id)-2:]
	}
	return id[:2]
}

// checkpointRefName returns refs/entire/checkpoints/<shard>/<id> for the git-refs
// store.
func checkpointRefName(id string) string {
	return checkpointRefPrefix + checkpointShard(id) + "/" + id
}

