13	// OpenOptions configures Open. The zero value uses the default committed-ref
14	// topology and attaches no blob fetcher.
15	type OpenOptions struct {
16		// BlobFetcher is the CLI-level on-demand blob fetcher. The checkpoint
17		// package cannot resolve it itself, so the CLI layer injects it here and
18		// Open attaches it to the constructed store(s). nil leaves on-demand
19		// fetching off.
20		BlobFetcher BlobFetchFunc
21	
22		// Refs overrides the default committed-ref topology. A non-nil value wins,
23		// e.g. attach pins reads to Primary via PrimaryAsRead().
24		Refs *PersistentRefs
25	}
26	
27	// Stores is the facade returned by Open: the persistent store plus the git-only
28	// ephemeral (shadow-branch) capability and resolved committed-ref topology.
29	type Stores struct {
30		// Persistent is the committed store that serves permanent reads and writes.
31		Persistent PersistentStore
32	
33		ephemeral EphemeralStore
34		refs      PersistentRefs
35	}
36	
37	// Open resolves the checkpoint storage topology and constructs the backing
38	// store(s). It keeps ref resolution, backend selection, and blob-fetcher wiring
39	// in one place. The primary is built through the backend registry; with no
40	// checkpoints config it resolves to the git-branch backend with no mirrors, so
41	// default behavior is unchanged. When mirrors are configured, the persistent
42	// store is a fan-out wrapper (reads from primary, best-effort writes to mirrors).
43	//
44	// Backend selection is read via settings.LoadCheckpointsConfig, which resolves
45	// like settings.Load: from the context's worktree root if set, else relative to
46	// the current working directory — not from repo. Callers opening a repository
47	// that is not the cwd should wrap ctx with that worktree root (as dispatch does).
48	// Resolution is fail-soft: a missing or unreadable settings file yields the
49	// default git-branch backend with no mirrors, preserving default behavior.
50	func Open(ctx context.Context, repo *git.Repository, opts OpenOptions) (*Stores, error) {
51		refs := resolveOpenRefs(ctx, opts)
52		env := OpenEnv{Repo: repo, BlobFetcher: opts.BlobFetcher, Refs: refs}
53	
54		cfg, err := settings.LoadCheckpointsConfig(ctx)
55		if err != nil {
56			return nil, fmt.Errorf("resolve checkpoints config: %w", err)
57		}
58	
59		primaryType := resolvePrimaryType(cfg)
60		primary, err := buildPrimary(ctx, env, primaryType, primaryConfig(cfg))
61		if err != nil {
62			return nil, err
63		}
64		mirrors, err := buildMirrors(ctx, env, cfg, primaryType)
65		if err != nil {
66			return nil, err
67		}
68	
69		return &Stores{
70			Persistent: newFanoutStore(primary, mirrors),
71			ephemeral:  newEphemeralStore(repo, refs),
72			refs:       refs,
73		}, nil
74	}
75	
76	// resolvePrimaryType returns the configured primary backend type, defaulting to
77	// the git-branch backend when none is configured.
78	func resolvePrimaryType(cfg *settings.CheckpointsConfig) string {
79		if cfg != nil && cfg.Primary.Type != "" {
80			return cfg.Primary.Type
81		}
82		return BackendTypeGitBranch
83	}
84	
85	// primaryConfig returns the primary backend's config block, if any.
86	func primaryConfig(cfg *settings.CheckpointsConfig) json.RawMessage {
87		if cfg == nil {
88			return nil
89		}
90		return cfg.Primary.Config
91	}
92	
93	// buildPrimary constructs the primary persistent store. The primary must be a
94	// git-backed backend: attach, resume, push, doctor, cleanup, and OPF all drive
95	// the primary's record through the repo and its refs, so a non-git-backed
96	// primary is rejected rather than silently half-supported.
97	func buildPrimary(ctx context.Context, env OpenEnv, typ string, raw json.RawMessage) (PersistentStore, error) {
98		b, err := lookupBackend(typ)
99		if err != nil {
100			return nil, fmt.Errorf("checkpoints.primary: %w", err)
101		}
102		if !b.gitBacked {
103			return nil, fmt.Errorf("checkpoints.primary.type %q cannot be the primary: only git-backed backends (e.g. %q) may be the primary", typ, BackendTypeGitBranch)
104		}
105		return build(ctx, env, typ, raw)
106	}
107	
108	// buildMirrors constructs the mirror writers. Each backend type may appear at
109	// most once across the topology (primary + mirrors), so a mirror cannot reuse
110	// the primary's type or another mirror's. This is the conservative form of "no
111	// two backends may write the same target": today two backends of the same type
112	// share the same refs/storage, so a duplicate type is a guaranteed collision
113	// (e.g. a git-branch mirror under a git-branch primary would double-write the v1
114	// branch). A future per-mirror config (same backend type pointed at a distinct
115	// repo/refs) could relax this; for now it is one of each type.
116	func buildMirrors(ctx context.Context, env OpenEnv, cfg *settings.CheckpointsConfig, primaryType string) ([]Writer, error) {
117		if cfg == nil || len(cfg.Mirrors) == 0 {
118			return nil, nil
119		}
120		seen := map[string]bool{primaryType: true}
121		mirrors := make([]Writer, 0, len(cfg.Mirrors))
122		for i, m := range cfg.Mirrors {
123			if _, err := lookupBackend(m.Type); err != nil {
124				return nil, fmt.Errorf("checkpoints.mirrors[%d]: %w", i, err)
125			}
126			if seen[m.Type] {
127				return nil, fmt.Errorf("checkpoints.mirrors[%d]: backend type %q is already used by the primary or another mirror; each backend type may appear at most once", i, m.Type)
128			}
129			seen[m.Type] = true
130			store, err := build(ctx, env, m.Type, m.Config)
131			if err != nil {
132				return nil, fmt.Errorf("checkpoints.mirrors[%d]: %w", i, err)
133			}
134			mirrors = append(mirrors, store)
135		}
136		return mirrors, nil
137	}
