	}
	return string(id[:2]) + "/" + string(id[2:])
}

// MarshalJSON implements json.Marshaler.
func (id CheckpointID) MarshalJSON() ([]byte, error) {
	data, err := json.Marshal(string(id))
	if err != nil {
