// For an ID shorter than two characters the whole ID is returned; an unrecognized
// ID falls back to the first-two (prefix) layout.
func (id CheckpointID) ShardFor() string {
	s := string(id)
	if len(s) < 2 {
		return s
	}
	if id.Kind() == KindULID {
		return s[len(s)-2:]
	}
	return s[:2]
}

